import{_ as a,o as t,c as r,a5 as s}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"HJ20 密码验证合格程序","description":"描述 密码要求: 1.长度超过8位 2.包括大小写字母.数字.其它符号,以上四种至少三种 3.不能有长度大于2的包含公共元素的子串重复 （注：其他符号不含空格或换行） 数据范围：输入的字符串长度满足 1≤�≤100 1≤ n ≤100 输入描述： 一组字符串。 输出描述： 如果符。","frontmatter":{"title":"HJ20 密码验证合格程序","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"描述 密码要求: 1.长度超过8位 2.包括大小写字母.数字.其它符号,以上四种至少三种 3.不能有长度大于2的包含公共元素的子串重复 （注：其他符号不含空格或换行） 数据范围：输入的字符串长度满足 1≤�≤100 1≤ n ≤100 输入描述： 一组字符串。 输出描述： 如果符。","sidebarWeight":96,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/多细节（中等）/HJ20 密码验证合格程序.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/多细节（中等）/HJ20 密码验证合格程序.md","filePath":"posts/前端面试与实战/03-算法训练/多细节（中等）/HJ20 密码验证合格程序.md"}'),o={name:"posts/前端面试与实战/03-算法训练/多细节（中等）/HJ20 密码验证合格程序.md"};function i(n,e,l,p,d,c){return t(),r("div",null,[...e[0]||(e[0]=[s('<div><h1 id="hj20-密码验证合格程序" tabindex="-1">HJ20 密码验证合格程序 <a class="header-anchor" href="#hj20-密码验证合格程序" aria-label="Permalink to &quot;HJ20 密码验证合格程序&quot;">​</a></h1><blockquote><p>本节目标：理解“HJ20 密码验证合格程序”的核心思路，并能把它用于实际开发或面试表达。 <strong>描述</strong> 密码要求: 1.长度超过8位 2.包括大小写字母.数字.其它符号,以上四种至少三种 3.不能有长度大于2的包含公共元素的子串重复 （注：其他符号不含空格或换行） 数据范围：输入的字符串长度满足 1≤�≤100 1≤<em>n</em>≤100 <strong>输入描述：</strong> 一组字符串。 <strong>输出描述：</strong> 如果符合要求输出：OK，否则输出NG <strong>示例1</strong> 输入： 021Abc9000021Abc9Abc1021ABC9000021$bc9000 ==复制== 输出： OKNGNGOK</p></blockquote><p>关键点：</p><ol><li>不能有长度超过2的子串重复，我们只要检查长度为3的子串，因为长度为4，长度为5的重复，必然会造成长度为3的重复；</li><li>只要检查在我们截取的子串是否in剩余字符串来判断重复即可；</li></ol><p>def is_valid_password(s):</p><h1 id="检查长度" tabindex="-1">检查长度 <a class="header-anchor" href="#检查长度" aria-label="Permalink to &quot;检查长度&quot;">​</a></h1><p>if len(s) &lt;= 8: return False types = [0, 0, 0, 0] # 分别对应 大写字母、小写字母、数字、其他符号</p><h1 id="检查类型多样性" tabindex="-1">检查类型多样性 <a class="header-anchor" href="#检查类型多样性" aria-label="Permalink to &quot;检查类型多样性&quot;">​</a></h1><p>for char in s: if char.isupper(): types[0] = 1 elif char.islower(): types[1] = 1 elif char.isdigit(): types[2] = 1 else: types[3] = 1 if sum(types) &lt; 3: return False</p><h1 id="检查无重复子串" tabindex="-1">检查无重复子串 <a class="header-anchor" href="#检查无重复子串" aria-label="Permalink to &quot;检查无重复子串&quot;">​</a></h1><p>for i in range(len(s) - 2): # 只需遍历到倒数第三个字符 sub = s[i:i+3] if sub in s[i+1:]: # 查看子串是否在后面的字符串中出现 return False return True</p><h1 id="读取并验证每个密码" tabindex="-1">读取并验证每个密码 <a class="header-anchor" href="#读取并验证每个密码" aria-label="Permalink to &quot;读取并验证每个密码&quot;">​</a></h1><p>while True: try: password = input() print(&quot;OK&quot; if is_valid_password(password) else &quot;NG&quot;) except EOFError: break</p></div>',1)])])}const _=a(o,[["render",i]]);export{u as __pageData,_ as default};
